sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?deathDate WHERE {
  VALUES ?film { dbr:Chad_Hanna dbr:The_Avenging_Shadow }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }
  FILTER(BOUND(?director))

  # director's death date (prefer dbp:deathDate)
  OPTIONAL { ?director dbp:deathDate ?dbpDeath . }
  OPTIONAL { ?director dbo:deathDate ?dboDeath . }
  BIND( COALESCE(?dbpDeath, ?dboDeath) AS ?deathDate )
}
LIMIT 100

